WORKFLOW_GUARDRAILS = {
"database-migration":"Require a tested backup and restore, schema compatibility across rolling application versions, migration rehearsal on representative data, row/count/checksum reconciliation, lock/downtime assessment and an approved stop/forward-fix plan.",
"emergency-hotfix":"Incident commander owns severity and scope; patch must be minimal, independently reviewed, tested against the incident, explicitly authorized and followed by normal regression and retrospective work.",
"production-release":"Promote the exact immutable artifact digest; use progressive rollout/canary where supported; define health and business stop thresholds; require named change authority and rollback owner.",
"rollback":"Check data/schema compatibility and irreversible side effects before rollback; choose rollback versus forward-fix explicitly; verify user-facing recovery and preserve incident evidence.",
"disaster-recovery":"Measure actual RTO/RPO during rehearsal; isolate recovery credentials and environment; validate restored data integrity and application dependencies before declaring recovery.",
"security-vulnerability-remediation":"Confirm affected asset/version and exploitability; keep active testing within written scope; prioritize exposure and exploit maturity; independently retest the fix and record any time-bound exception.",
"api-version-upgrade":"Inventory consumers and usage before changing contracts; publish compatibility policy, migration examples, dual-run/deprecation dates and consumer test evidence.",
"dependency-update":"Verify provenance, changelog and advisory impact; inspect transitive dependency/license changes; run regression and security checks; pin the resolved version and document rollback.",
"product-retirement":"Inventory users, integrations, data, legal retention and supplier dependencies; communicate notice; verify export/migration, access removal, deletion and audit closure.",
"ci-cd-pipeline-creation":"Treat workflow code, runners, secrets and artifacts as a supply-chain boundary; pin actions, scope permissions, isolate untrusted pull requests and verify artifact provenance.",
"infrastructure-provisioning":"Review IaC plan, state locking, IAM/network exposure, cost/quota and drift; require approved change window and tested recovery before apply.",
"incident-response":"Assign commander/scribe/comms roles; maintain timeline and impact; prioritize containment and safe restoration; communicate only verified facts.",
}
def phase_profile(workflow_id,phase,index):
    rules=PHASE_SPECIAL_CASES+PHASE_RULES
    for pattern,instruction,evidence,exit_criteria in rules:
        if re.search(pattern,phase,re.I):
            break
    else:
        instruction=f"Complete the {phase.lower()} phase with explicit inputs, accountable owner, recorded decisions and verifiable outcome."
        evidence=["phase work product","verification evidence","handoff record"]
        exit_criteria="The accountable owner accepts the output and all blocking issues have an owner."
    guard=WORKFLOW_GUARDRAILS.get(workflow_id)
    if guard:
        instruction += " Workflow-specific control: " + guard
        evidence=evidence+["workflow-specific safety/control evidence"]
    return {"instruction":instruction,"evidence":evidence,"exit_criteria":exit_criteria}

